#include <cstdio>
#include <cstdlib>
#include <openssl/dsa.h>
#include <openssl/pem.h>
#include <string>

std::string create_dsa_key_securely() {
    // Generate DSA parameters using OpenSSL C API
    DSA *dsa = DSA_new();
    if (!dsa) {
        return "";
    }

    // Generate DSA parameters with 2048 bits
    if (!DSA_generate_parameters_ex(dsa, 2048, nullptr, 0, nullptr, nullptr, nullptr)) {
        DSA_free(dsa);
        return "";
    }

    // Generate private key
    if (!DSA_generate_key_ex(dsa)) {
        DSA_free(dsa);
        return "";
    }

    // Write private key to memory in PEM format
    BIO *bio = BIO_new(BIO_s_mem());
    if (!PEM_write_bio_DSA PRIVATEKEY_bio(bio, dsa)) {
        DSA_free(dsa);
        return "";
    }

    // Get the PEM data as a string
    char *pem_data;
    long pem_len = BIO_get_mem_data(bio, &pem_data);
    std::string result(pem_data, pem_len);

    BIO_free(bio);
    DSA_free(dsa);
    return result;
}

#include <cstdio>
#include <cstdlib>
#include <string>
#include <unistd.h>

int main() {
    char param_filename[] = "/tmp/tempXXXXXX";
    int fd = mkstemp(param_filename);
    if (fd == -1) {
        perror("mkstemp");
        return 1;
    }

    // Generate DSA parameters
    std::string command1 = "openssl dsaparam -out " + std::string(param_filename) + " 2048";
    FILE* pipe = popen(command1.c_str(), "r");
    if (!pipe) {
        std::cerr << "popen() failed!" << std::endl;
        close(fd);
        return 1;
    }

    // Read output
    char buffer[128];
    std::string output;
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
        output += buffer;
    }
    pclose(pipe);

    // Generate DSA private key
    std::string command2 = "openssl gendsa " + std::string(param_filename);
    pipe = popen(command2.c_str(), "r");
    if (!pipe) {
        std::cerr << "popen() failed!" << std::endl;
        close(fd);
        return 1;
    }

    output = "";
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
        output += buffer;
    }
    pclose(pipe);

    // Clean up
    unlink(param_filename);
    close(fd);

    std::cout << "Generated DSA key:\n" << output << std::endl;
    return 0;
}
